 function focusFirst(dialog){const target=dialog.querySelector('[autofocus],button:not([disabled]),a[href],input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]')||dialog;try{target.focus({preventScroll:true});}catch{target.focus();}}
