  dialog.showModal=function(){if(this.open)return;const backdrop=document.createElement('div');backdrop.className='mobile-dialog-backdrop';const previous=document.activeElement;const entry={dialog:this,backdrop,previous};stack.push(entry);document.body.append(backdrop);this.setAttribute('open','');this.setAttribute('aria-modal','true');this.dataset.mobileModal='true';this.style.zIndex=String(1001+stack.length*2);backdrop.style.zIndex=String(1000+stack.length*2);backdrop.addEventListener('click',()=>{if(stack[stack.length-1]===entry)cancel(this);});document.body.classList.add('mobile-modal-open');focusFirst(this);};
